keyRow.Size = UDim2.new(1, -40, 0, 110); keyRow.Position = UDim2.fromOffset(20, 170)
keyRow.BackgroundTransparency = 1; keyRow.Visible = false
local keyLabel = Instance.new("TextLabel", keyRow)
